webApi.a:expression:
a!localVariables(
  /* 1. Extract Body & ID */
  local!body: if(
    isnull(http!request.body),
    null,
    #"SYSTEM_SYSRULES_fromJson_v1"(http!request.body)
  ),
  local!vehicleIds: index(local!body, "vehicleIds", {}),
  local!maintenanceIds: index(local!body, "maintenanceIds", {}),
  local!partOrderIds: index(local!body, "partOrderIds", {}),
  /* 2. Logic Flow */
  if(
    and(
      isnull(local!vehicleIds),
      isnull(local!maintenanceIds),
      isnull(local!partOrderIds)
      ),
    /* Error: 400 Bad Request */
    #"SYSTEM_SYSRULES_httpResponse_v1"(
      statusCode: 400,
      headers: {
        #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
      },
      body: #"SYSTEM_SYSRULES_toJson_v1"({ error: "No identifiers provided in the body for vehicleIds, maintenanceIds, or partOrderIds." })
    ),

    /* Success: Start Process */
    #"SYSTEM_SYSRULES_startProcess3"(
      processModel: #"_a-0000ef40-8303-8000-9be5-011c48011c48_812851", 
      processParameters: { 
        "vehicleIdentifiers": tointeger(local!vehicleIds),
        "maintenanceIdentifiers": tointeger(local!maintenanceIds),
        "partOrderIdentifiers": tointeger(local!partOrderIds)

      },

      /* CRITICAL FIX: No curly braces { } around this response */
      onSuccess: #"SYSTEM_SYSRULES_httpResponse_v1"(
        statusCode: 200,
        headers: {
          #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
        },
        body: #"SYSTEM_SYSRULES_toJson_v1"({
          status: "Success",
          message: "Sync started for provided identifiers"
        })
      ),

      onError: #"SYSTEM_SYSRULES_httpResponse_v1"(
        statusCode: 500,
        body: #"SYSTEM_SYSRULES_toJson_v1"({ error: "Failed to start sync process." })
      )
    )
  )
)
